export type IsoconName = keyof typeof ISOCONS

/** Every icon the set carries, for the style guide. */
export const ISOCON_NAMES = Object.keys(ISOCONS) as IsoconName[]

export function Isocon({
  name,
  stroke = 1,
  draw = false,
  className,
  ...props
}: {
  name: IsoconName
  /** Stroke width in screen pixels. */
  stroke?: number
  /** Trace the outline in when the surrounding `group/iso` is hovered. */
  draw?: boolean
} & Omit<React.ComponentProps<"svg">, "stroke">) {
  const icon = ISOCONS[name]
  return (
    <svg
      viewBox={icon.viewBox}
      fill="none"
      stroke="currentColor"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      className={cn("h-auto w-full overflow-visible", draw && "iso-draw", className)}
      {...props}
    >
      {icon.d.map((d, i) => (
        <path key={i} d={d} pathLength={1} strokeWidth={stroke} vectorEffect="non-scaling-stroke" />
      ))}
    </svg>
  )
}
